1357|LZ4_FORCE_INLINE int LZ4_compress_generic(
1358|                 LZ4_stream_t_internal* const cctx,
1359|                 const char* const src,
1360|                 char* const dst,
1361|                 const int srcSize,
1362|                 int *inputConsumed, /* only written when outputDirective == fillOutput */
1363|                 const int dstCapacity,
1364|                 const limitedOutput_directive outputDirective,
1365|                 const tableType_t tableType,
1366|                 const dict_directive dictDirective,
1367|                 const dictIssue_directive dictIssue,
1368|                 const int acceleration)
1369|{
1370|    DEBUGLOG(5, "LZ4_compress_generic: srcSize=%i, dstCapacity=%i",
1371|                srcSize, dstCapacity);
1372|
1373|    if ((U32)srcSize > (U32)LZ4_MAX_INPUT_SIZE) { return 0; }  /* Unsupported srcSize, too large (or negative) */
1374|    if (srcSize == 0) {   /* src == NULL supported if srcSize == 0 */
1375|        if (outputDirective != notLimited && dstCapacity <= 0) return 0;  /* no output, can't write anything */
1376|        DEBUGLOG(5, "Generating an empty block");
1377|        assert(outputDirective == notLimited || dstCapacity >= 1);
1378|        assert(dst != NULL);
1379|        dst[0] = 0;
1380|        if (outputDirective == fillOutput) {
1381|            assert (inputConsumed != NULL);
1382|            *inputConsumed = 0;
1383|        }
1384|        return 1;
1385|    }
1386|    assert(src != NULL);
1387|
1388|    return LZ4_compress_generic_validated(cctx, src, dst, srcSize,
1389|                inputConsumed, /* only written into if outputDirective == fillOutput */
1390|                dstCapacity, outputDirective,
1391|                tableType, dictDirective, dictIssue, acceleration);
1392|}

