2658|int LZ4_decompress_safe_continue (LZ4_streamDecode_t* LZ4_streamDecode, const char* source, char* dest, int compressedSize, int maxOutputSize)
2659|{
2660|    LZ4_streamDecode_t_internal* lz4sd = &LZ4_streamDecode->internal_donotuse;
2661|    int result;
2662|
2663|    if (lz4sd->prefixSize == 0) {
2664|        /* The first call, no dictionary yet. */
2665|        assert(lz4sd->extDictSize == 0);
2666|        result = LZ4_decompress_safe(source, dest, compressedSize, maxOutputSize);
2667|        if (result <= 0) return result;
2668|        lz4sd->prefixSize = (size_t)result;
2669|        lz4sd->prefixEnd = (BYTE*)dest + result;
2670|    } else if (lz4sd->prefixEnd == (BYTE*)dest) {
2671|        /* They're rolling the current segment. */
2672|        if (lz4sd->prefixSize >= 64 KB - 1)
2673|            result = LZ4_decompress_safe_withPrefix64k(source, dest, compressedSize, maxOutputSize);
2674|        else if (lz4sd->extDictSize == 0)
2675|            result = LZ4_decompress_safe_withSmallPrefix(source, dest, compressedSize, maxOutputSize,
2676|                                                         lz4sd->prefixSize);
2677|        else
2678|            result = LZ4_decompress_safe_doubleDict(source, dest, compressedSize, maxOutputSize,
2679|                                                    lz4sd->prefixSize, lz4sd->externalDict, lz4sd->extDictSize);
2680|        if (result <= 0) return result;
2681|        lz4sd->prefixSize += (size_t)result;
2682|        lz4sd->prefixEnd  += result;
2683|    } else {
2684|        /* The buffer wraps around, or they're switching to another buffer. */
2685|        lz4sd->extDictSize = lz4sd->prefixSize;
2686|        lz4sd->externalDict = lz4sd->prefixEnd - lz4sd->extDictSize;
2687|        result = LZ4_decompress_safe_forceExtDict(source, dest, compressedSize, maxOutputSize,
2688|                                                  lz4sd->externalDict, lz4sd->extDictSize);
2689|        if (result <= 0) return result;
2690|        lz4sd->prefixSize = (size_t)result;
2691|        lz4sd->prefixEnd  = (BYTE*)dest + result;
2692|    }
2693|
2694|    return result;
2695|}

1671|void LZ4_attach_dictionary(LZ4_stream_t* workingStream, const LZ4_stream_t* dictionaryStream)
1672|{
1673|    const LZ4_stream_t_internal* dictCtx = (dictionaryStream == NULL) ? NULL :
1674|        &(dictionaryStream->internal_donotuse);
1675|
1676|    DEBUGLOG(4, "LZ4_attach_dictionary (%p, %p, size %u)",
1677|             (void*)workingStream, (void*)dictionaryStream,
1678|             dictCtx != NULL ? dictCtx->dictSize : 0);
1679|
1680|    if (dictCtx != NULL) {
1681|        /* If the current offset is zero, we will never look in the
1682|         * external dictionary context, since there is no value a table
1683|         * entry can take that indicate a miss. In that case, we need
1684|         * to bump the offset to something non-zero.
1685|         */
1686|        if (workingStream->internal_donotuse.currentOffset == 0) {
1687|            workingStream->internal_donotuse.currentOffset = 64 KB;
1688|        }
1689|
1690|        /* Don't actually attach an empty dictionary.
1691|         */
1692|        if (dictCtx->dictSize == 0) {
1693|            dictCtx = NULL;
1694|        }
1695|    }
1696|    workingStream->internal_donotuse.dictCtx = dictCtx;
1697|}

