289|/* LZ4HC_encodeSequence() :
290| * @return : 0 if ok,
291| *           1 if buffer issue detected */
292|LZ4_FORCE_INLINE int LZ4HC_encodeSequence (
293|    const BYTE** _ip,
294|    BYTE** _op,
295|    const BYTE** _anchor,
296|    int matchLength,
297|    int offset,
298|    limitedOutput_directive limit,
299|    BYTE* oend)
300|{
301|#define ip      (*_ip)
302|#define op      (*_op)
303|#define anchor  (*_anchor)
304|
305|    BYTE* const token = op++;
306|
307|#if defined(LZ4_DEBUG) && (LZ4_DEBUG >= 6)
308|    static const BYTE* start = NULL;
309|    static U32 totalCost = 0;
310|    U32 const pos = (start==NULL) ? 0 : (U32)(anchor - start); /* only works for single segment */
311|    U32 const ll = (U32)(ip - anchor);
312|    U32 const llAdd = (ll>=15) ? ((ll-15) / 255) + 1 : 0;
313|    U32 const mlAdd = (matchLength>=19) ? ((matchLength-19) / 255) + 1 : 0;
314|    U32 const cost = 1 + llAdd + ll + 2 + mlAdd;
315|    if (start==NULL) start = anchor;  /* only works for single segment */
316|    DEBUGLOG(6, "pos:%7u -- literals:%4u, match:%4i, offset:%5i, cost:%4u + %5u",
317|                pos,
318|                (U32)(ip - anchor), matchLength, offset,
319|                cost, totalCost);
320|# if 1 /* only works on single segment data */
321|    HEX_CMP(7, ip, ip-offset, matchLength);
322|# endif
323|    totalCost += cost;
324|#endif
325|
326|    /* Encode Literal length */
327|    {   size_t litLen = (size_t)(ip - anchor);
328|        LZ4_STATIC_ASSERT(notLimited == 0);
329|        /* Check output limit */
330|        if (limit && ((op + (litLen / 255) + litLen + (2 + 1 + LASTLITERALS)) > oend)) {
331|            DEBUGLOG(6, "Not enough room to write %i literals (%i bytes remaining)",
332|                    (int)litLen, (int)(oend - op));
333|            return 1;
334|        }
335|        if (litLen >= RUN_MASK) {
336|            size_t len = litLen - RUN_MASK;
337|            *token = (RUN_MASK << ML_BITS);
338|            for(; len >= 255 ; len -= 255) *op++ = 255;
339|            *op++ = (BYTE)len;
340|        } else {
341|            *token = (BYTE)(litLen << ML_BITS);
342|        }
343|
344|        /* Copy Literals */
345|        LZ4_wildCopy8(op, anchor, op + litLen);
346|        op += litLen;
347|    }
348|
349|    /* Encode Offset */
350|    assert(offset <= LZ4_DISTANCE_MAX );
351|    assert(offset > 0);
352|    LZ4_writeLE16(op, (U16)(offset)); op += 2;
353|
354|    /* Encode MatchLength */
355|    assert(matchLength >= MINMATCH);
356|    {   size_t mlCode = (size_t)matchLength - MINMATCH;
357|        if (limit && (op + (mlCode / 255) + (1 + LASTLITERALS) > oend)) {
358|            DEBUGLOG(6, "Not enough room to write match length");
359|            return 1;   /* Check output limit */
360|        }
361|        if (mlCode >= ML_MASK) {
362|            *token += ML_MASK;
363|            mlCode -= ML_MASK;
364|            for(; mlCode >= 510 ; mlCode -= 510) { *op++ = 255; *op++ = 255; }
365|            if (mlCode >= 255) { mlCode -= 255; *op++ = 255; }
366|            *op++ = (BYTE)mlCode;
367|        } else {
368|            *token += (BYTE)(mlCode);
369|    }   }
370|
371|    /* Prepare next loop */
372|    ip += matchLength;
373|    anchor = ip;
374|
375|    return 0;
376|
377|#undef ip
378|#undef op
379|#undef anchor
