389|static LZ4HC_match_t LZ4HC_searchExtDict(const BYTE* ip, U32 ipIndex,
390|        const BYTE* const iLowLimit, const BYTE* const iHighLimit,
391|        const LZ4HC_CCtx_internal* dictCtx, U32 gDictEndIndex,
392|        int currentBestML, int nbAttempts)
393|{
394|    size_t const lDictEndIndex = (size_t)(dictCtx->end - dictCtx->prefixStart) + dictCtx->dictLimit;
395|    U32 lDictMatchIndex = dictCtx->hashTable[LZ4HC_hashPtr(ip)];
396|    U32 matchIndex = lDictMatchIndex + gDictEndIndex - (U32)lDictEndIndex;
397|    int offset = 0, sBack = 0;
398|    assert(lDictEndIndex <= 1 GB);
399|    if (lDictMatchIndex>0)
400|        DEBUGLOG(7, "lDictEndIndex = %zu, lDictMatchIndex = %u", lDictEndIndex, lDictMatchIndex);
401|    while (ipIndex - matchIndex <= LZ4_DISTANCE_MAX && nbAttempts--) {
402|        const BYTE* const matchPtr = dictCtx->prefixStart - dictCtx->dictLimit + lDictMatchIndex;
403|
404|        if (LZ4_read32(matchPtr) == LZ4_read32(ip)) {
405|            int mlt;
406|            int back = 0;
407|            const BYTE* vLimit = ip + (lDictEndIndex - lDictMatchIndex);
408|            if (vLimit > iHighLimit) vLimit = iHighLimit;
409|            mlt = (int)LZ4_count(ip+MINMATCH, matchPtr+MINMATCH, vLimit) + MINMATCH;
410|            back = (ip > iLowLimit) ? LZ4HC_countBack(ip, matchPtr, iLowLimit, dictCtx->prefixStart) : 0;
411|            mlt -= back;
412|            if (mlt > currentBestML) {
413|                currentBestML = mlt;
414|                offset = (int)(ipIndex - matchIndex);
415|                sBack = back;
416|                DEBUGLOG(7, "found match of length %i within extDictCtx", currentBestML);
417|        }   }
418|
419|        {   U32 const nextOffset = DELTANEXTU16(dictCtx->chainTable, lDictMatchIndex);
420|            lDictMatchIndex -= nextOffset;
421|            matchIndex -= nextOffset;
422|    }   }
423|
424|    {   LZ4HC_match_t md;
425|        md.len = currentBestML;
426|        md.off = offset;
427|        md.back = sBack;
428|        return md;
429|    }
