446|static LZ4HC_match_t LZ4MID_searchExtDict(const BYTE* ip, U32 ipIndex,
447|        const BYTE* const iHighLimit,
448|        const LZ4HC_CCtx_internal* dictCtx, U32 gDictEndIndex)
449|{
450|    size_t const lDictEndIndex = (size_t)(dictCtx->end - dictCtx->prefixStart) + dictCtx->dictLimit;
451|    const U32* const hash4Table = dictCtx->hashTable;
452|    const U32* const hash8Table = hash4Table + LZ4MID_HASHTABLESIZE;
453|    DEBUGLOG(7, "LZ4MID_searchExtDict (ipIdx=%u)", ipIndex);
454|
455|    /* search long match first */
456|    {   U32 l8DictMatchIndex = hash8Table[LZ4MID_hash8Ptr(ip)];
457|        U32 m8Index = l8DictMatchIndex + gDictEndIndex - (U32)lDictEndIndex;
458|        assert(lDictEndIndex <= 1 GB);
459|        if (ipIndex - m8Index <= LZ4_DISTANCE_MAX) {
460|            const BYTE* const matchPtr = dictCtx->prefixStart - dictCtx->dictLimit + l8DictMatchIndex;
461|            const size_t safeLen = MIN(lDictEndIndex - l8DictMatchIndex, (size_t)(iHighLimit - ip));
462|            int mlt = (int)LZ4_count(ip, matchPtr, ip + safeLen);
463|            if (mlt >= MINMATCH) {
464|                LZ4HC_match_t md;
465|                DEBUGLOG(7, "Found long ExtDict match of len=%u", mlt);
466|                md.len = mlt;
467|                md.off = (int)(ipIndex - m8Index);
468|                md.back = 0;
469|                return md;
470|            }
471|        }
472|    }
473|
474|    /* search for short match second */
475|    {   U32 l4DictMatchIndex = hash4Table[LZ4MID_hash4Ptr(ip)];
476|        U32 m4Index = l4DictMatchIndex + gDictEndIndex - (U32)lDictEndIndex;
477|        if (ipIndex - m4Index <= LZ4_DISTANCE_MAX) {
478|            const BYTE* const matchPtr = dictCtx->prefixStart - dictCtx->dictLimit + l4DictMatchIndex;
479|            const size_t safeLen = MIN(lDictEndIndex - l4DictMatchIndex, (size_t)(iHighLimit - ip));
480|            int mlt = (int)LZ4_count(ip, matchPtr, ip + safeLen);
481|            if (mlt >= MINMATCH) {
482|                LZ4HC_match_t md;
483|                DEBUGLOG(7, "Found short ExtDict match of len=%u", mlt);
484|                md.len = mlt;
485|                md.off = (int)(ipIndex - m4Index);
486|                md.back = 0;
487|                return md;
488|            }
489|        }
490|    }
491|
492|    /* nothing found */
493|    {   LZ4HC_match_t const md = {0, 0, 0 };
494|        return md;
495|    }
