511|/* Fill hash tables with references into dictionary.
512| * The resulting table is only exploitable by LZ4MID (level 2) */
513|static void
514|LZ4MID_fillHTable (LZ4HC_CCtx_internal* cctx, const void* dict, size_t size)
515|{
516|    U32* const hash4Table = cctx->hashTable;
517|    U32* const hash8Table = hash4Table + LZ4MID_HASHTABLESIZE;
518|    const BYTE* const prefixPtr = (const BYTE*)dict;
519|    U32 const prefixIdx = cctx->dictLimit;
520|    U32 const target = prefixIdx + (U32)size - LZ4MID_HASHSIZE;
521|    U32 idx = cctx->nextToUpdate;
522|    assert(dict == cctx->prefixStart);
523|    DEBUGLOG(4, "LZ4MID_fillHTable (size:%zu)", size);
524|    if (size <= LZ4MID_HASHSIZE)
525|        return;
526|
527|    for (; idx < target; idx += 3) {
528|        ADDPOS4(prefixPtr+idx-prefixIdx, idx);
529|        ADDPOS8(prefixPtr+idx+1-prefixIdx, idx+1);
530|    }
531|
532|    idx = (size > 32 KB + LZ4MID_HASHSIZE) ? target - 32 KB : cctx->nextToUpdate;
533|    for (; idx < target; idx += 1) {
534|        ADDPOS8(prefixPtr+idx-prefixIdx, idx);
535|    }
536|
537|    cctx->nextToUpdate = target;
538|}
