548|/* preconditions:
549| * - *srcSizePtr within [1, LZ4_MAX_INPUT_SIZE]
550| * - src is valid
551| * - maxOutputSize >= 1
552| * - dst is valid
553| */
554|static int LZ4MID_compress (
555|    LZ4HC_CCtx_internal* const ctx,
556|    const char* const src,
557|    char* const dst,
558|    int* srcSizePtr,
559|    int const maxOutputSize,
560|    const limitedOutput_directive limit,
561|    const dictCtx_directive dict
562|    )
563|{
564|    U32* const hash4Table = ctx->hashTable;
565|    U32* const hash8Table = hash4Table + LZ4MID_HASHTABLESIZE;
566|    const BYTE* ip = (const BYTE*)src;
567|    const BYTE* anchor = ip;
568|    const BYTE* const iend = ip + *srcSizePtr;
569|    const BYTE* const mflimit = iend - MFLIMIT;
570|    const BYTE* const matchlimit = (iend - LASTLITERALS);
571|    const BYTE* const ilimit = (iend - LZ4MID_HASHSIZE);
572|    BYTE* op = (BYTE*)dst;
573|    BYTE* oend = op + maxOutputSize;
574|
575|    const BYTE* const prefixPtr = ctx->prefixStart;
576|    const U32 prefixIdx = ctx->dictLimit;
577|    const U32 ilimitIdx = (U32)(ilimit - prefixPtr) + prefixIdx;
578|    const BYTE* const dictStart = ctx->dictStart;
579|    const U32 dictIdx = ctx->lowLimit;
580|    const U32 gDictEndIndex = ctx->lowLimit;
581|    const LZ4MID_searchIntoDict_f searchIntoDict = (dict == usingDictCtxHc) ? select_searchDict_function(ctx->dictCtx) : NULL;
582|    unsigned matchLength;
583|    unsigned matchDistance;
584|
585|    DEBUGLOG(5, "LZ4MID_compress (%i bytes)", *srcSizePtr);
586|
587|    /* preconditions verifications */
588|    if (dict == usingDictCtxHc) DEBUGLOG(5, "usingDictCtxHc");
589|    assert(*srcSizePtr > 0);
590|    assert(*srcSizePtr <= LZ4_MAX_INPUT_SIZE);
591|    assert(src != NULL);
592|    assert(maxOutputSize >= 1);
593|    assert(dst != NULL);
594|
595|    if (limit == fillOutput) oend -= LASTLITERALS;  /* Hack for support LZ4 format restriction */
596|    if (*srcSizePtr < LZ4_minLength)
597|        goto _lz4mid_last_literals;  /* Input too small, no compression (all literals) */
598|
599|    /* main loop */
600|    while (ip <= mflimit) {
601|        const U32 ipIndex = (U32)(ip - prefixPtr) + prefixIdx;
602|        /* search long match */
603|        {   U32 const h8 = LZ4MID_hash8Ptr(ip);
604|            U32 const pos8 = hash8Table[h8];
605|            assert(h8 < LZ4MID_HASHTABLESIZE);
606|            assert(pos8 < ipIndex);
607|            LZ4MID_addPosition(hash8Table, h8, ipIndex);
608|            if (ipIndex - pos8 <= LZ4_DISTANCE_MAX) {
609|                /* match candidate found */
610|                if (pos8 >= prefixIdx) {
611|                    const BYTE* const matchPtr = prefixPtr + pos8 - prefixIdx;
612|                    assert(matchPtr < ip);
613|                    matchLength = LZ4_count(ip, matchPtr, matchlimit);
614|                    if (matchLength >= MINMATCH) {
615|                        DEBUGLOG(7, "found long match at pos %u (len=%u)", pos8, matchLength);
616|                        matchDistance = ipIndex - pos8;
617|                        goto _lz4mid_encode_sequence;
618|                    }
619|                } else {
620|                    if (pos8 >= dictIdx) {
621|                        /* extDict match candidate */
622|                        const BYTE* const matchPtr = dictStart + (pos8 - dictIdx);
623|                        const size_t safeLen = MIN(prefixIdx - pos8, (size_t)(matchlimit - ip));
624|                        matchLength = LZ4_count(ip, matchPtr, ip + safeLen);
625|                        if (matchLength >= MINMATCH) {
626|                            DEBUGLOG(7, "found long match at ExtDict pos %u (len=%u)", pos8, matchLength);
627|                            matchDistance = ipIndex - pos8;
628|                            goto _lz4mid_encode_sequence;
629|                        }
630|                    }
631|                }
632|        }   }
633|        /* search short match */
634|        {   U32 const h4 = LZ4MID_hash4Ptr(ip);
635|            U32 const pos4 = hash4Table[h4];
636|            assert(h4 < LZ4MID_HASHTABLESIZE);
637|            assert(pos4 < ipIndex);
638|            LZ4MID_addPosition(hash4Table, h4, ipIndex);
639|            if (ipIndex - pos4 <= LZ4_DISTANCE_MAX) {
640|                /* match candidate found */
641|                if (pos4 >= prefixIdx) {
642|                /* only search within prefix */
643|                    const BYTE* const matchPtr = prefixPtr + (pos4 - prefixIdx);
644|                    assert(matchPtr < ip);
645|                    assert(matchPtr >= prefixPtr);
646|                    matchLength = LZ4_count(ip, matchPtr, matchlimit);
647|                    if (matchLength >= MINMATCH) {
648|                        /* short match found, let's just check ip+1 for longer */
649|                        U32 const h8 = LZ4MID_hash8Ptr(ip+1);
650|                        U32 const pos8 = hash8Table[h8];
651|                        U32 const m2Distance = ipIndex + 1 - pos8;
652|                        matchDistance = ipIndex - pos4;
653|                        if ( m2Distance <= LZ4_DISTANCE_MAX
654|                        && pos8 >= prefixIdx /* only search within prefix */
655|                        && likely(ip < mflimit)
656|                        ) {
657|                            const BYTE* const m2Ptr = prefixPtr + (pos8 - prefixIdx);
658|                            unsigned ml2 = LZ4_count(ip+1, m2Ptr, matchlimit);
659|                            if (ml2 > matchLength) {
660|                                LZ4MID_addPosition(hash8Table, h8, ipIndex+1);
661|                                ip++;
662|                                matchLength = ml2;
663|                                matchDistance = m2Distance;
664|                        }   }
665|                        goto _lz4mid_encode_sequence;
666|                    }
667|                } else {
668|                    if (pos4 >= dictIdx) {
669|                        /* extDict match candidate */
670|                        const BYTE* const matchPtr = dictStart + (pos4 - dictIdx);
671|                        const size_t safeLen = MIN(prefixIdx - pos4, (size_t)(matchlimit - ip));
672|                        matchLength = LZ4_count(ip, matchPtr, ip + safeLen);
673|                        if (matchLength >= MINMATCH) {
674|                            DEBUGLOG(7, "found match at ExtDict pos %u (len=%u)", pos4, matchLength);
675|                            matchDistance = ipIndex - pos4;
676|                            goto _lz4mid_encode_sequence;
677|                        }
678|                    }
679|                }
680|        }   }
681|        /* no match found in prefix */
682|        if ( (dict == usingDictCtxHc)
683|          && (ipIndex - gDictEndIndex < LZ4_DISTANCE_MAX - 8) ) {
684|            /* search a match into external dictionary */
685|            LZ4HC_match_t dMatch = searchIntoDict(ip, ipIndex,
686|                    matchlimit,
687|                    ctx->dictCtx, gDictEndIndex);
688|            if (dMatch.len >= MINMATCH) {
689|                DEBUGLOG(7, "found Dictionary match (offset=%i)", dMatch.off);
690|                assert(dMatch.back == 0);
691|                matchLength = (unsigned)dMatch.len;
692|                matchDistance = (unsigned)dMatch.off;
693|                goto _lz4mid_encode_sequence;
694|            }
695|        }
696|        /* no match found */
697|        ip += 1 + ((ip-anchor) >> 9);  /* skip faster over incompressible data */
698|        continue;
699|
700|_lz4mid_encode_sequence:
701|        /* catch back */
702|        while (((ip > anchor) & ((U32)(ip-prefixPtr) > matchDistance)) && (unlikely(ip[-1] == ip[-(int)matchDistance-1]))) {
703|            ip--;  matchLength++;
704|        };
705|
706|        /* fill table with beginning of match */
707|        ADDPOS8(ip+1, ipIndex+1);
708|        ADDPOS8(ip+2, ipIndex+2);
709|        ADDPOS4(ip+1, ipIndex+1);
710|
711|        /* encode */
712|        {   BYTE* const saved_op = op;
713|            /* LZ4HC_encodeSequence always updates @op; on success, it updates @ip and @anchor */
714|            if (LZ4HC_encodeSequence(UPDATABLE(ip, op, anchor),
715|                    (int)matchLength, (int)matchDistance,
716|                    limit, oend) ) {
717|                op = saved_op;  /* restore @op value before failed LZ4HC_encodeSequence */
718|                goto _lz4mid_dest_overflow;
719|            }
720|        }
721|
722|        /* fill table with end of match */
723|        {   U32 endMatchIdx = (U32)(ip-prefixPtr) + prefixIdx;
724|            U32 pos_m2 = endMatchIdx - 2;
725|            if (pos_m2 < ilimitIdx) {
726|                if (likely(ip - prefixPtr > 5)) {
727|                    ADDPOS8(ip-5, endMatchIdx - 5);
728|                }
729|                ADDPOS8(ip-3, endMatchIdx - 3);
730|                ADDPOS8(ip-2, endMatchIdx - 2);
731|                ADDPOS4(ip-2, endMatchIdx - 2);
732|                ADDPOS4(ip-1, endMatchIdx - 1);
733|            }
734|        }
735|    }
736|
737|_lz4mid_last_literals:
738|    /* Encode Last Literals */
739|    {   size_t lastRunSize = (size_t)(iend - anchor);  /* literals */
740|        size_t llAdd = (lastRunSize + 255 - RUN_MASK) / 255;
741|        size_t const totalSize = 1 + llAdd + lastRunSize;
742|        if (limit == fillOutput) oend += LASTLITERALS;  /* restore correct value */
743|        if (limit && (op + totalSize > oend)) {
744|            if (limit == limitedOutput) return 0;  /* not enough space in @dst */
745|            /* adapt lastRunSize to fill 'dest' */
746|            lastRunSize  = (size_t)(oend - op) - 1 /*token*/;
747|            llAdd = (lastRunSize + 256 - RUN_MASK) / 256;
748|            lastRunSize -= llAdd;
749|        }
750|        DEBUGLOG(6, "Final literal run : %i literals", (int)lastRunSize);
751|        ip = anchor + lastRunSize;  /* can be != iend if limit==fillOutput */
752|
753|        if (lastRunSize >= RUN_MASK) {
754|            size_t accumulator = lastRunSize - RUN_MASK;
755|            *op++ = (RUN_MASK << ML_BITS);
756|            for(; accumulator >= 255 ; accumulator -= 255)
757|                *op++ = 255;
758|            *op++ = (BYTE) accumulator;
759|        } else {
760|            *op++ = (BYTE)(lastRunSize << ML_BITS);
761|        }
762|        assert(lastRunSize <= (size_t)(oend - op));
763|        LZ4_memcpy(op, anchor, lastRunSize);
764|        op += lastRunSize;
765|    }
766|
767|    /* End */
768|    DEBUGLOG(5, "compressed %i bytes into %i bytes", *srcSizePtr, (int)((char*)op - dst));
769|    assert(ip >= (const BYTE*)src);
770|    assert(ip <= iend);
771|    *srcSizePtr = (int)(ip - (const BYTE*)src);
772|    assert((char*)op >= dst);
773|    assert(op <= oend);
774|    assert((char*)op - dst < INT_MAX);
775|    return (int)((char*)op - dst);
776|
777|_lz4mid_dest_overflow:
778|    if (limit == fillOutput) {
779|        /* Assumption : @ip, @anchor, @optr and @matchLength must be set correctly */
780|        size_t const ll = (size_t)(ip - anchor);
781|        size_t const ll_addbytes = (ll + 240) / 255;
782|        size_t const ll_totalCost = 1 + ll_addbytes + ll;
783|        BYTE* const maxLitPos = oend - 3; /* 2 for offset, 1 for token */
784|        DEBUGLOG(6, "Last sequence is overflowing : %u literals, %u remaining space",
785|                (unsigned)ll, (unsigned)(oend-op));
786|        if (op + ll_totalCost <= maxLitPos) {
787|            /* ll validated; now adjust match length */
788|            size_t const bytesLeftForMl = (size_t)(maxLitPos - (op+ll_totalCost));
789|            size_t const maxMlSize = MINMATCH + (ML_MASK-1) + (bytesLeftForMl * 255);
790|            assert(maxMlSize < INT_MAX);
791|            if ((size_t)matchLength > maxMlSize) matchLength= (unsigned)maxMlSize;
792|            if ((oend + LASTLITERALS) - (op + ll_totalCost + 2) - 1 + matchLength >= MFLIMIT) {
793|            DEBUGLOG(6, "Let's encode a last sequence (ll=%u, ml=%u)", (unsigned)ll, matchLength);
794|                LZ4HC_encodeSequence(UPDATABLE(ip, op, anchor),
795|                        (int)matchLength, (int)matchDistance,
796|                        notLimited, oend);
797|        }   }
798|        DEBUGLOG(6, "Let's finish with a run of literals (%u bytes left)", (unsigned)(oend-op));
799|        goto _lz4mid_last_literals;
800|    }
801|    /* compression failed */
802|    return 0;
