810|/* Update chains up to ip (excluded) */
811|LZ4_FORCE_INLINE void LZ4HC_Insert (LZ4HC_CCtx_internal* hc4, const BYTE* ip)
812|{
813|    U16* const chainTable = hc4->chainTable;
814|    U32* const hashTable  = hc4->hashTable;
815|    const BYTE* const prefixPtr = hc4->prefixStart;
816|    U32 const prefixIdx = hc4->dictLimit;
817|    U32 const target = (U32)(ip - prefixPtr) + prefixIdx;
818|    U32 idx = hc4->nextToUpdate;
819|    assert(ip >= prefixPtr);
820|    assert(target >= prefixIdx);
821|
822|    while (idx < target) {
823|        U32 const h = LZ4HC_hashPtr(prefixPtr+idx-prefixIdx);
824|        size_t delta = idx - hashTable[h];
825|        if (delta>LZ4_DISTANCE_MAX) delta = LZ4_DISTANCE_MAX;
826|        DELTANEXTU16(chainTable, idx) = (U16)delta;
827|        hashTable[h] = idx;
828|        idx++;
829|    }
830|
831|    hc4->nextToUpdate = target;
832|}
