841|static U32 LZ4HC_rotatePattern(size_t const rotate, U32 const pattern)
842|{
843|    size_t const bitsToRotate = (rotate & (sizeof(pattern) - 1)) << 3;
844|    if (bitsToRotate == 0) return pattern;
845|    return LZ4HC_rotl32(pattern, (int)bitsToRotate);
