848|/* LZ4HC_countPattern() :
849| * pattern32 must be a sample of repetitive pattern of length 1, 2 or 4 (but not 3!) */
850|static unsigned
851|LZ4HC_countPattern(const BYTE* ip, const BYTE* const iEnd, U32 const pattern32)
852|{
853|    const BYTE* const iStart = ip;
854|    reg_t const pattern = (sizeof(pattern)==8) ?
855|        (reg_t)pattern32 + (((reg_t)pattern32) << (sizeof(pattern)*4)) : pattern32;
856|
857|    while (likely(ip < iEnd-(sizeof(pattern)-1))) {
858|        reg_t const diff = LZ4_read_ARCH(ip) ^ pattern;
859|        if (!diff) { ip+=sizeof(pattern); continue; }
860|        ip += LZ4_NbCommonBytes(diff);
861|        return (unsigned)(ip - iStart);
862|    }
863|
864|    if (LZ4_isLittleEndian()) {
865|        reg_t patternByte = pattern;
866|        while ((ip<iEnd) && (*ip == (BYTE)patternByte)) {
867|            ip++; patternByte >>= 8;
868|        }
869|    } else {  /* big endian */
870|        U32 bitOffset = (sizeof(pattern)*8) - 8;
871|        while (ip < iEnd) {
872|            BYTE const byte = (BYTE)(pattern >> bitOffset);
873|            if (*ip != byte) break;
874|            ip ++; bitOffset -= 8;
875|    }   }
876|
877|    return (unsigned)(ip - iStart);
878|}
