880|/* LZ4HC_reverseCountPattern() :
881| * pattern must be a sample of repetitive pattern of length 1, 2 or 4 (but not 3!)
882| * read using natural platform endianness */
883|static unsigned
884|LZ4HC_reverseCountPattern(const BYTE* ip, const BYTE* const iLow, U32 pattern)
885|{
886|    const BYTE* const iStart = ip;
887|
888|    while (likely(ip >= iLow+4)) {
889|        if (LZ4_read32(ip-4) != pattern) break;
890|        ip -= 4;
891|    }
892|    {   const BYTE* bytePtr = (const BYTE*)(&pattern) + 3; /* works for any endianness */
893|        while (likely(ip>iLow)) {
894|            if (ip[-1] != *bytePtr) break;
895|            ip--; bytePtr--;
896|    }   }
897|    return (unsigned)(iStart - ip);
898|}
