1390|        size_t const ll_totalCost = 1 + ll_addbytes + ll;
1391|        BYTE* const maxLitPos = oend - 3; /* 2 for offset, 1 for token */
1392|        DEBUGLOG(6, "Last sequence overflowing");
1393|        op = optr;  /* restore correct out pointer */
1394|        if (op + ll_totalCost <= maxLitPos) {
1395|            /* ll validated; now adjust match length */
1396|            size_t const bytesLeftForMl = (size_t)(maxLitPos - (op+ll_totalCost));
1397|            size_t const maxMlSize = MINMATCH + (ML_MASK-1) + (bytesLeftForMl * 255);
1398|            assert(maxMlSize < INT_MAX); assert(m1.len >= 0);
1399|            if ((size_t)m1.len > maxMlSize) m1.len = (int)maxMlSize;
1400|            if ((oend + LASTLITERALS) - (op + ll_totalCost + 2) - 1 + m1.len >= MFLIMIT) {
1401|                LZ4HC_encodeSequence(UPDATABLE(ip, op, anchor), m1.len, m1.off, notLimited, oend);
1402|        }   }
1403|        goto _last_literals;
1404|    }
1405|    /* compression failed */
1406|    return 0;
1407|}
