1418|static int
1419|LZ4HC_compress_generic_internal (
1420|            LZ4HC_CCtx_internal* const ctx,
1421|            const char* const src,
1422|            char* const dst,
1423|            int* const srcSizePtr,
1424|            int const dstCapacity,
1425|            int cLevel,
1426|            const limitedOutput_directive limit,
1427|            const dictCtx_directive dict
1428|            )
1429|{
1430|    DEBUGLOG(5, "LZ4HC_compress_generic_internal(src=%p, srcSize=%d, dstCapacity=%d)",
1431|                src, *srcSizePtr, dstCapacity);
1432|
1433|    /* input sanitization */
1434|    if ((U32)*srcSizePtr > (U32)LZ4_MAX_INPUT_SIZE) return 0;  /* Unsupported input size (too large or negative) */
1435|    if (dstCapacity < 1) return 0;   /* Invalid: impossible to store anything */
1436|    assert(dst); /* since dstCapacity >= 1, dst must be valid */
1437|    if (*srcSizePtr == 0) { *dst = 0; return 1; }
1438|    assert(src != NULL); /* since *srcSizePtr >= 1, src must be valid */
1439|
1440|    ctx->end += *srcSizePtr;
1441|    {   cParams_t const cParam = LZ4HC_getCLevelParams(cLevel);
1442|        HCfavor_e const favor = ctx->favorDecSpeed ? favorDecompressionSpeed : favorCompressionRatio;
1443|        int result;
1444|
1445|        if (cParam.strat == lz4mid) {
1446|            result = LZ4MID_compress(ctx,
1447|                                src, dst, srcSizePtr, dstCapacity,
1448|                                limit, dict);
1449|        } else if (cParam.strat == lz4hc) {
1450|            result = LZ4HC_compress_hashChain(ctx,
1451|                                src, dst, srcSizePtr, dstCapacity,
1452|                                cParam.nbSearches, limit, dict);
1453|        } else {
1454|            assert(cParam.strat == lz4opt);
1455|            result = LZ4HC_compress_optimal(ctx,
1456|                                src, dst, srcSizePtr, dstCapacity,
1457|                                cParam.nbSearches, cParam.targetLength, limit,
1458|                                cLevel >= LZ4HC_CLEVEL_MAX,   /* ultra mode */
1459|                                dict, favor);
1460|        }
1461|        if (result <= 0) ctx->dirty = 1;
1462|        return result;
1463|    }
