1677|/* LZ4_loadDictHC() :
1678| * LZ4_streamHCPtr is presumed properly initialized */
1679|int LZ4_loadDictHC (LZ4_streamHC_t* LZ4_streamHCPtr,
1680|              const char* dictionary, int dictSize)
1681|{
1682|    LZ4HC_CCtx_internal* const ctxPtr = &LZ4_streamHCPtr->internal_donotuse;
1683|    cParams_t cp;
1684|    DEBUGLOG(4, "LZ4_loadDictHC(ctx:%p, dict:%p, dictSize:%d, clevel=%d)", LZ4_streamHCPtr, dictionary, dictSize, ctxPtr->compressionLevel);
1685|    assert(dictSize >= 0);
1686|    assert(LZ4_streamHCPtr != NULL);
1687|    if (dictSize > 64 KB) {
1688|        dictionary += (size_t)dictSize - 64 KB;
1689|        dictSize = 64 KB;
1690|    }
1691|    /* need a full initialization, there are bad side-effects when using resetFast() */
1692|    {   int const cLevel = ctxPtr->compressionLevel;
1693|        LZ4_initStreamHC(LZ4_streamHCPtr, sizeof(*LZ4_streamHCPtr));
1694|        LZ4_setCompressionLevel(LZ4_streamHCPtr, cLevel);
1695|        cp = LZ4HC_getCLevelParams(cLevel);
1696|    }
1697|    LZ4HC_init_internal (ctxPtr, (const BYTE*)dictionary);
1698|    ctxPtr->end = (const BYTE*)dictionary + dictSize;
1699|    if (cp.strat == lz4mid) {
1700|        LZ4MID_fillHTable (ctxPtr, dictionary, (size_t)dictSize);
1701|    } else {
1702|        if (dictSize >= LZ4HC_HASHSIZE) LZ4HC_Insert (ctxPtr, ctxPtr->end-3);
1703|    }
1704|    return dictSize;
