1711|/* compression */
1712|
1713|static void LZ4HC_setExternalDict(LZ4HC_CCtx_internal* ctxPtr, const BYTE* newBlock)
1714|{
1715|    DEBUGLOG(4, "LZ4HC_setExternalDict(%p, %p)", ctxPtr, newBlock);
1716|    if ( (ctxPtr->end >= ctxPtr->prefixStart + 4)
1717|      && (LZ4HC_getCLevelParams(ctxPtr->compressionLevel).strat != lz4mid) ) {
1718|        LZ4HC_Insert (ctxPtr, ctxPtr->end-3);  /* Referencing remaining dictionary content */
1719|    }
1720|
1721|    /* Only one memory segment for extDict, so any previous extDict is lost at this stage */
1722|    ctxPtr->lowLimit  = ctxPtr->dictLimit;
1723|    ctxPtr->dictStart  = ctxPtr->prefixStart;
1724|    ctxPtr->dictLimit += (U32)(ctxPtr->end - ctxPtr->prefixStart);
1725|    ctxPtr->prefixStart = newBlock;
1726|    ctxPtr->end  = newBlock;
1727|    ctxPtr->nextToUpdate = ctxPtr->dictLimit;   /* match referencing will resume from there */
1728|
1729|    /* cannot reference an extDict and a dictCtx at the same time */
1730|    ctxPtr->dictCtx = NULL;
1731|}
