1733|static int
1734|LZ4_compressHC_continue_generic (LZ4_streamHC_t* LZ4_streamHCPtr,
1735|                                 const char* src, char* dst,
1736|                                 int* srcSizePtr, int dstCapacity,
1737|                                 limitedOutput_directive limit)
1738|{
1739|    LZ4HC_CCtx_internal* const ctxPtr = &LZ4_streamHCPtr->internal_donotuse;
1740|    DEBUGLOG(5, "LZ4_compressHC_continue_generic(ctx=%p, src=%p, srcSize=%d, limit=%d)",
1741|                LZ4_streamHCPtr, src, *srcSizePtr, limit);
1742|    assert(ctxPtr != NULL);
1743|    /* auto-init if forgotten */
1744|    if (ctxPtr->prefixStart == NULL)
1745|        LZ4HC_init_internal (ctxPtr, (const BYTE*) src);
1746|
1747|    /* Check overflow */
1748|    if ((size_t)(ctxPtr->end - ctxPtr->prefixStart) + ctxPtr->dictLimit > 2 GB) {
1749|        size_t dictSize = (size_t)(ctxPtr->end - ctxPtr->prefixStart);
1750|        if (dictSize > 64 KB) dictSize = 64 KB;
1751|        LZ4_loadDictHC(LZ4_streamHCPtr, (const char*)(ctxPtr->end) - dictSize, (int)dictSize);
1752|    }
1753|
1754|    /* Check if blocks follow each other */
1755|    if ((const BYTE*)src != ctxPtr->end)
1756|        LZ4HC_setExternalDict(ctxPtr, (const BYTE*)src);
1757|
1758|    /* Check overlapping input/dictionary space */
1759|    {   const BYTE* sourceEnd = (const BYTE*) src + *srcSizePtr;
1760|        const BYTE* const dictBegin = ctxPtr->dictStart;
1761|        const BYTE* const dictEnd   = ctxPtr->dictStart + (ctxPtr->dictLimit - ctxPtr->lowLimit);
1762|        if ((sourceEnd > dictBegin) && ((const BYTE*)src < dictEnd)) {
1763|            if (sourceEnd > dictEnd) sourceEnd = dictEnd;
1764|            ctxPtr->lowLimit += (U32)(sourceEnd - ctxPtr->dictStart);
1765|            ctxPtr->dictStart += (U32)(sourceEnd - ctxPtr->dictStart);
1766|            /* invalidate dictionary is it's too small */
1767|            if (ctxPtr->dictLimit - ctxPtr->lowLimit < LZ4HC_HASHSIZE) {
1768|                ctxPtr->lowLimit = ctxPtr->dictLimit;
1769|                ctxPtr->dictStart = ctxPtr->prefixStart;
1770|    }   }   }
1771|
1772|    return LZ4HC_compress_generic (ctxPtr, src, dst, srcSizePtr, dstCapacity, ctxPtr->compressionLevel, limit);
1773|}
