1790|/* LZ4_saveDictHC :
1791| * save history content
1792| * into a user-provided buffer
1793| * which is then used to continue compression
1794| */
1795|int LZ4_saveDictHC (LZ4_streamHC_t* LZ4_streamHCPtr, char* safeBuffer, int dictSize)
1796|{
1797|    LZ4HC_CCtx_internal* const streamPtr = &LZ4_streamHCPtr->internal_donotuse;
1798|    int const prefixSize = (int)(streamPtr->end - streamPtr->prefixStart);
1799|    DEBUGLOG(5, "LZ4_saveDictHC(%p, %p, %d)", LZ4_streamHCPtr, safeBuffer, dictSize);
1800|    assert(prefixSize >= 0);
1801|    if (dictSize > 64 KB) dictSize = 64 KB;
1802|    if (dictSize < 4) dictSize = 0;
1803|    if (dictSize > prefixSize) dictSize = prefixSize;
1804|    if (safeBuffer == NULL) assert(dictSize == 0); /* a NULL buffer with !0 size is invalid */
1805|    if (dictSize > 0)
1806|        LZ4_memmove(safeBuffer, streamPtr->end - dictSize, (size_t)dictSize);
1807|    {   U32 const endIndex = (U32)(streamPtr->end - streamPtr->prefixStart) + streamPtr->dictLimit;
1808|        streamPtr->end = (safeBuffer == NULL) ? NULL : (const BYTE*)safeBuffer + dictSize;
1809|        streamPtr->prefixStart = (const BYTE*)safeBuffer;
1810|        streamPtr->dictLimit = endIndex - (U32)dictSize;
1811|        streamPtr->lowLimit = endIndex - (U32)dictSize;
1812|        streamPtr->dictStart = streamPtr->prefixStart;
1813|        if (streamPtr->nextToUpdate < streamPtr->dictLimit)
1814|            streamPtr->nextToUpdate = streamPtr->dictLimit;
1815|    }
1816|    return dictSize;
