1820|/* ================================================
1821| *  LZ4 Optimal parser (levels [LZ4HC_CLEVEL_OPT_MIN - LZ4HC_CLEVEL_MAX])
1822| * ===============================================*/
1823|typedef struct {
1824|    int price;
1825|    int off;
1826|    int mlen;
1827|    int litlen;
1828|} LZ4HC_optimal_t;
1829|
1830|/* price in bytes */
1831|LZ4_FORCE_INLINE int LZ4HC_literalsPrice(int const litlen)
1832|{
1833|    int price = litlen;
1834|    assert(litlen >= 0);
1835|    if (litlen >= (int)RUN_MASK)
1836|        price += 1 + ((litlen-(int)RUN_MASK) / 255);
1837|    return price;
1838|}
1839|
1840|/* requires mlen >= MINMATCH */
1841|LZ4_FORCE_INLINE int LZ4HC_sequencePrice(int litlen, int mlen)
1842|{
