89|static void test_decompress(
90|    FILE* outFp,
91|    FILE* inpFp,
92|    size_t messageMaxBytes,
93|    size_t ringBufferBytes)
94|{
95|    assert(outFp != NULL); assert(inpFp != NULL);
96|
97|    LZ4_streamDecode_t* const lz4StreamDecode = LZ4_createStreamDecode();
98|    char* const cmpBuf = (char*) malloc(LZ4_COMPRESSBOUND(messageMaxBytes));
99|    char* const decBuf = (char*) malloc(ringBufferBytes);
100|    int decOffset = 0;
101|
102|    for ( ; ; )
103|    {
104|        uint16_t cmpBytes = 0;
105|
106|        if (read_uint16(inpFp, &cmpBytes) != 1) break;
107|        if (cmpBytes == 0) break;
108|        if (read_bin(inpFp, cmpBuf, cmpBytes) != cmpBytes) break;
109|
110|        {
111|            char* const decPtr = &decBuf[decOffset];
112|            const int decBytes = LZ4_decompress_safe_continue(
113|                lz4StreamDecode, cmpBuf, decPtr, cmpBytes, (int) messageMaxBytes);
114|            if (decBytes <= 0) break;
115|            write_bin(outFp, decPtr, decBytes);
116|
117|            // Add and wraparound the ringbuffer offset
118|            decOffset += decBytes;
119|            if ((size_t)decOffset >= ringBufferBytes - messageMaxBytes) decOffset = 0;
120|        }
121|    }
122|
