108|void test_decompress(FILE* outFp, FILE* inpFp, void *dict, int dictSize, int offset, int length)
109|{
110|    assert(outFp != NULL); assert(inpFp != NULL);
111|
112|    LZ4_streamDecode_t lz4StreamDecode_body;
113|    LZ4_streamDecode_t* lz4StreamDecode = &lz4StreamDecode_body;
114|
115|    /* The blocks [currentBlock, endBlock) contain the data we want */
116|    int currentBlock = offset / BLOCK_BYTES;
117|    int endBlock = ((offset + length - 1) / BLOCK_BYTES) + 1;
118|
119|    char decBuf[BLOCK_BYTES];
120|    int offsets[MAX_BLOCKS];
121|
122|    /* Special cases */
123|    if (length == 0) { return; }
124|
125|    /* Read the magic bytes */
126|    {
127|        char magic[sizeof(kTestMagic)];
128|        size_t read = read_bin(inpFp, magic, sizeof(magic));
129|        if (read != sizeof(magic)) { exit(1); }
130|        if (memcmp(kTestMagic, magic, sizeof(magic))) { exit(2); }
131|    }
132|
133|    /* Read the offsets tail */
134|    {
135|        int numOffsets;
136|        int block;
137|        int *offsetsPtr = offsets;
138|        seek_bin(inpFp, -4, SEEK_END);
139|        read_int(inpFp, &numOffsets);
140|        if (numOffsets <= endBlock) { exit(3); }
141|        seek_bin(inpFp, -4 * (numOffsets + 1), SEEK_END);
142|        for (block = 0; block <= endBlock; ++block) {
143|            read_int(inpFp, offsetsPtr++);
144|        }
145|    }
146|    /* Seek to the first block to read */
147|    seek_bin(inpFp, offsets[currentBlock], SEEK_SET);
148|    offset = offset % BLOCK_BYTES;
149|
150|    /* Start decoding */
151|    for(; currentBlock < endBlock; ++currentBlock) {
152|        char cmpBuf[LZ4_COMPRESSBOUND(BLOCK_BYTES)];
153|        /* The difference in offsets is the size of the block */
154|        int  cmpBytes = offsets[currentBlock + 1] - offsets[currentBlock];
155|        {
156|            const size_t read = read_bin(inpFp, cmpBuf, (size_t)cmpBytes);
157|            if(read != (size_t)cmpBytes) { exit(4); }
158|        }
159|
160|        /* Load the dictionary */
161|        LZ4_setStreamDecode(lz4StreamDecode, (const char*) dict, dictSize);
162|        {
163|            const int decBytes = LZ4_decompress_safe_continue(
164|                lz4StreamDecode, cmpBuf, decBuf, cmpBytes, BLOCK_BYTES);
165|            if(decBytes <= 0) { exit(5); }
166|            {
167|                /* Write out the part of the data we care about */
168|                int blockLength = MIN(length, (decBytes - offset));
169|                write_bin(outFp, decBuf + offset, (size_t)blockLength);
170|                offset = 0;
171|                length -= blockLength;
172|            }
173|        }
174|    }
175|}

