657|static void LZ4F_initStream(void* ctx,
658|                            const LZ4F_CDict* cdict,
659|                            int level,
660|                            LZ4F_blockMode_t blockMode) {
661|    if (level < LZ4HC_CLEVEL_MIN) {
662|        /* In these cases, we will call LZ4_compress_fast_continue(),
663|         * which needs an already reset context. Otherwise, we'll call a
664|         * one-shot API. The non-continued APIs internally perform their own
665|         * resets at the beginning of their calls, where they know what
666|         * tableType they need the context to be in. So in that case this
667|         * would be misguided / wasted work. */
668|        if (cdict) {
669|            LZ4_resetStream_fast((LZ4_stream_t*)ctx);
670|            LZ4_attach_dictionary((LZ4_stream_t*)ctx, cdict->fastCtx);
671|        } else if (blockMode == LZ4F_blockLinked) {
672|            /* Clear the table, rather than LZ4_resetStream_fast() :
673|             * output doesn't depend on the context's history,
674|             * and it's faster, unless the frame is tiny. */
675|            LZ4_initStream(ctx, sizeof(LZ4_stream_t));
676|        }
677|        /* In these cases, we'll call a one-shot API.
678|         * The non-continued APIs internally perform their own resets
679|         * at the beginning of their calls, where they know
680|         * which tableType they need the context to be in.
681|         * Therefore, a reset here would be wasted work. */
682|    } else {
683|        LZ4_resetStreamHC_fast((LZ4_streamHC_t*)ctx, level);
684|        if (cdict)
685|            LZ4_attach_HC_dictionary((LZ4_streamHC_t*)ctx, cdict->HCCtx);
686|    }
687|}

197|static void state_attachDictRoundTrip(state_t* state)
198|{
199|    char const* dict = state->data.buf;
200|    size_t const dictSize = state_trimDict(state);
201|    LZ4_stream_t* dictStream = LZ4_createStream();
202|    LZ4_loadDict(dictStream, dict, dictSize);
203|    LZ4_attach_dictionary(state->cstream, dictStream);
204|    LZ4_setStreamDecode(state->dstream, dict, dictSize);
205|    state_randomRoundTrip(state, state_prefixRoundTrip, state_extDictRoundTrip);
206|    LZ4_freeStream(dictStream);
207|}

210|static void
211|LZ4_compressResetStream(const struct compressionParameters* cparams)
212|{
213|    LZ4_resetStream_fast(cparams->LZ4_stream);
214|    LZ4_attach_dictionary(cparams->LZ4_stream, cparams->LZ4_dictStream);
215|}

